INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] 재귀적 강제 삭제 rm -rf',1,100,'tool_input','regex','(?i)\brm\b.{0,80}(?:-[a-z]*r[a-z]*f[a-z]*|-[a-z]*f[a-z]*r[a-z]*|--recursive|--no-preserve-root)','deny','시스템이나 테스트 환경을 영구 손상시킬 수 있는 재귀적 강제 삭제(rm -rf / rm --recursive)는 금지합니다',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] 시스템 중요 디렉터리 삭제',1,100,'tool_input','regex','\brm\b[^"''\n]{0,60}["''\s](/|/etc|/bin|/usr|/boot|/var|/lib|/sys|/proc|/dev|/sbin|/root)','deny','시스템 중요 경로 삭제는 금지합니다',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] 디스크 포맷 mkfs',1,100,'tool_input','regex','\bmkfs\b','deny','디스크 포맷(mkfs)은 금지합니다',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] 디스크 장치 덮어쓰기 dd',1,100,'tool_input','regex','\bdd\b[^|\n]{0,100}\bof=\s*/dev/[a-zA-Z]','deny','dd로 디스크 장치를 덮어쓰는 작업은 금지합니다',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] Fork 폭탄',1,100,'tool_input','regex',':\(\)\s*\{[^}]*:\|:','deny','Fork 폭탄 실행은 금지합니다',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] 시스템 종료 / 재시작',1,100,'tool_input','regex','\b(?:shutdown|reboot|halt|poweroff|init\s+[06])\b','deny','시스템 종료 또는 재시작 명령은 금지합니다',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] 모든 프로세스 강제 종료',1,100,'tool_input','regex','\bkill\s+-9\s+-1\b|\bkillall\s+-9\b','deny','모든 프로세스를 종료하는 kill -9 -1 / killall -9는 금지합니다',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] 디스크 완전 삭제 shred / wipe',1,100,'tool_input','regex','\b(?:shred|wipe)\b[^|\n]{0,80}/dev/[a-zA-Z]','deny','디스크 장치에 대한 shred/wipe 삭제는 금지합니다',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] 방화벽 규칙 초기화',1,100,'tool_input','regex','\biptables\s+(?:-F|--flush)\b|\bnft\s+flush\s+ruleset\b','deny','방화벽 규칙 전체 삭제(iptables -F / nft flush)는 금지합니다',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] SQL DROP DATABASE / TABLE / SCHEMA',1,90,'tool_input','regex','(?i)\bDROP\s+(?:DATABASE|TABLE|SCHEMA|INDEX|VIEW|TABLESPACE|USER|ROLE)\b','deny','DB 객체를 복구 불가능하게 삭제할 수 있는 DROP은 금지합니다',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] SQL TRUNCATE',1,90,'tool_input','regex','(?i)\bTRUNCATE\s+(?:TABLE\s+)?\w','deny','테이블 전체 데이터를 삭제할 수 있는 TRUNCATE는 금지합니다',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] MongoDB drop / dropDatabase',1,90,'tool_input','regex','(?i)\.(?:dropDatabase|dropCollection|drop)\s*\(','deny','MongoDB drop 작업은 금지합니다',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] Redis FLUSHALL / FLUSHDB',1,90,'tool_input','regex','(?i)\b(?:FLUSHALL|FLUSHDB)\b','deny','모든 캐시 데이터를 삭제할 수 있는 Redis FLUSHALL / FLUSHDB는 금지합니다',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] curl / wget의 DELETE 요청',1,80,'tool_input','regex','(?i)\bcurl\b[^|\n&;"]{0,300}(?:-X\s*DELETE|--request\s+DELETE|-XDELETE)|\bwget\b[^|\n&;"]{0,300}--method[=\s]+DELETE','deny','대상 시스템의 데이터를 삭제할 수 있는 curl/wget HTTP DELETE 요청은 금지합니다',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] Python HTTP 클라이언트 DELETE(requests/httpx/aiohttp)',1,80,'tool_input','regex','(?i)\b(?:requests|httpx|aiohttp|urllib\.request)\.delete\s*\(|session\.delete\s*\(|client\.delete\s*\(','deny','Python HTTP 클라이언트로 DELETE 요청을 전송하는 것은 금지합니다',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] 스크립트의 HTTP DELETE 메서드(JS/일반)',1,80,'tool_input','regex','(?i)axios\.delete\s*\(|method\s*[:=]\s*[''"]DELETE[''"]','deny','스크립트에서 HTTP DELETE를 지정하고 전송하는 것은 금지합니다',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] 일괄 초기화 / 삭제 API 경로',1,80,'tool_input','regex','(?i)/(?:clear|wipe|flush|purge|truncate|drop|destroy|factory[-_]reset|reset[-_]all)(?:[/?#"''\s]|$)','deny','일괄 데이터를 삭제하는 API(/clear /wipe /flush /purge /truncate /drop /destroy 등) 호출은 금지합니다',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] 파괴적인 시스템 명령',1,100,'tool_input','regex','(?i)\b(rm\s+-rf\s+/|mkfs|dd\s+if=|:\(\)\s*\{|shutdown|reboot|>\s*/dev/sd)','deny','파괴적 명령을 거부했습니다(rm -rf / / mkfs / dd / fork bomb / 종료·재시작 / 디스크 덮어쓰기)',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] 데이터 외부 전송 파이프라인',0,80,'tool_input','regex','(?i)(curl|wget|nc|ncat)\b[^|]*\b(\|\s*(curl|wget|nc))','deny','명령 출력을 curl/wget/nc로 외부 전송하는 데이터 유출 의심 작업을 거부했습니다',0,60,'deny');
INSERT INTO intercept_rules(name,enabled,priority,match_target,match_type,pattern,action,message,timeout_enabled,timeout_seconds,timeout_action) VALUES ('[기본] 삭제 API 경로',1,80,'tool_input','regex','(?i)/(?:(?:delete|remove|unlink|erase|destroy)[-\w]*|del)(?:[/?#"''\s]|$)','deny','/delete /remove /unlink /erase 등 삭제 API는 HTTP 메서드와 관계없이 금지합니다. GET/POST만으로 실제 대상 데이터를 삭제하는 API도 포함됩니다',0,60,'deny');
